-- Fitness & Gym: four differentiated service-led templates. Additive and idempotent; no existing rows are deleted.
ON CONFLICT (template_key) DO UPDATE SET category_slug=EXCLUDED.category_slug,name=EXCLUDED.name,tagline=EXCLUDED.tagline,description=EXCLUDED.description,business_types=EXCLUDED.business_types,feature_flags=EXCLUDED.feature_flags,sort_order=EXCLUDED.sort_order,is_builtin=EXCLUDED.is_builtin;

ON CONFLICT (template_key,design_version) DO UPDATE SET design_spec=EXCLUDED.design_spec,preview_settings=EXCLUDED.preview_settings,source_commit=EXCLUDED.source_commit,is_active=EXCLUDED.is_active,updated_at=now();
UPDATE builder.template_designs SET is_active=false WHERE template_key IN ('ironforge-performance-club','pulse-athletic-studio','balance-house-yoga-pilates','athletelab-performance-coaching') AND design_version<>1;

ON CONFLICT (template_key,page_key) DO UPDATE SET page_type=EXCLUDED.page_type,title=EXCLUDED.title,slug=EXCLUDED.slug,sort_order=EXCLUDED.sort_order,page_spec=EXCLUDED.page_spec,is_required=EXCLUDED.is_required,is_active=EXCLUDED.is_active;
